console.log(mode, theme);
console.log(typeof mode, typeof theme);

// TODO: annotate the parameters only; let the rest be inferred
function discount(price, rate) {
  const off = price * rate;
  return price - off;
}

console.log(discount(100, 0.2));

solution.code:
function discount(price: number, rate: number) {
  const off = price * rate; // inferred: number
  return price - off;       // return type inferred: number
}

console.log(discount(100, 0.2));
